/* Current-model drawings and previews. Exporting never changes floors, plans or undo history. */
(function(){
'use strict';
let threePromise=null,threeView=null,threeToken=0,stackSnapshot=null,pngBusy=false,threeName='Building';
const fmt=n=>`${n>0?'+':''}${Number(n).toFixed(2)} m`;
function prepare(){finishWidthEdit(false);finishDrag(true);closeToolbarMenus();closeConnectionMenu();}
function sheetBounds(f){
 const rs=f.rooms||[];if(!rs.length)return{x:-2,y:-2,w:24,h:18};
 const xs=rs.flatMap(r=>[r.x,r.x+r.w]),ys=rs.flatMap(r=>[r.y,r.y+r.h]);
 for(const e of f.externals||[f.external].filter(Boolean)){const r=rs.find(r=>r.id===e.room);if(!r)continue;const vertical=['e','w'].includes(e.side),x=vertical?(e.side==='e'?r.x+r.w:r.x):r.x+r.w/2,y=vertical?r.y+r.h/2:(e.side==='s'?r.y+r.h:r.y),dx=e.side==='e'?1:e.side==='w'?-1:0,dy=e.side==='s'?1:e.side==='n'?-1:0,half=String(e.label||'').length*.12;xs.push(x+dx*4,x+dx*3-half,x+dx*3+half);ys.push(y+dy*4,y+dy*3+1.1)}
 for(const a of f.annotations||[]){const half=String(a.text||'').length*.12;xs.push(a.x-half,a.x+half);ys.push(a.y-.5,a.y+.5)}
 const x=Math.min(...xs)-3,y=Math.min(...ys)-3;return{x,y,w:Math.max(...xs)+3-x,h:Math.max(...ys)+3-y};
}
function floorSheet(id=floorId){
 const f=model.floors[id];if(!f)throw Error('That floor no longer exists.');
 const previous=floorId,b=sheetBounds(f);let markup;
 try{floorId=id;markup=planMarkup(true,false)}finally{floorId=previous}
 const width=1800,planHeight=Math.max(420,Math.min(2000,(width-120)*b.h/b.w)),height=planHeight+235,title=currentBuilding().name;
 const size=Math.max(18,Math.min(34,1600/(Math.max(1,title.length)*.58))),caption=`${id} / ${f.name} / ${fmt(f.z||0)}`,captionSize=Math.max(12,Math.min(24,1600/(Math.max(1,caption.length)*.58)));
 return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img"><title>${esc(title)} · ${esc(id)} · ${esc(f.name)}</title><rect width="100%" height="100%" fill="#f7f7f2"/><g font-family="system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif" letter-spacing="normal" word-spacing="normal" fill="#253240"><text x="60" y="57" font-size="${size}" font-weight="bold">${esc(title)}</text><text x="60" y="94" font-size="${captionSize}">${esc(caption)}</text><text x="60" y="128" font-size="15" fill="#596979">CURRENT FLOOR PLAN · METRES · ${esc(new Date().toISOString().slice(0,10))}</text></g><svg x="60" y="153" width="1680" height="${planHeight}" viewBox="${b.x} ${b.y} ${b.w} ${b.h}" preserveAspectRatio="xMidYMid meet">${markup}</svg><line x1="60" x2="1740" y1="${height-54}" y2="${height-54}" stroke="#c8cfd3"/><text x="60" y="${height-27}" font-family="system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif" letter-spacing="normal" word-spacing="normal" font-size="14" fill="#65717d">Concept plan · not a construction or life-safety drawing · current edits, no selection overlays</text></svg>`;
}
function stackSheet(data,name){
 const width=1600,height=Math.max(720,data.levels.length*78+250),b=data.bounds,top=155,bottom=height-115,availableW=width-390,spanX=Math.max(10,b.maxX-b.minX),spanZ=Math.max(4,b.maxZ-b.minZ),scale=Math.min(availableW/spanX,(bottom-top)/spanZ),left=330+(availableW-spanX*scale)/2;
 const sx=x=>left+(x-b.minX)*scale,sy=z=>bottom-(z-b.minZ)*scale;
 let s=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img"><title>${esc(name)} · Vertical stack</title><rect width="100%" height="100%" fill="#f7f7f2"/><g font-family="system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif" letter-spacing="normal" word-spacing="normal" fill="#253240"><text x="55" y="55" font-size="${Math.max(18,Math.min(32,1450/Math.max(1,name.length)/.58))}" font-weight="bold">${esc(name)}</text><text x="55" y="93" font-size="23">Vertical stack / east–west elevation</text><text x="55" y="126" font-size="14" fill="#596979">Actual floor elevations · room depths overlap in this schematic projection</text>`;
 for(const l of data.levels){s+=`<path d="M310 ${sy(l.z)}H${width-45}" stroke="#c3ccd2" stroke-width="1" stroke-dasharray="5 5"/>`;const boxes=[...l.boxes].sort((a,b)=>b.y-a.y);for(const q of boxes){if(q.kind==='opening-marker')continue;const x=sx(q.x),y=sy(q.z+q.height),w=q.w*scale,h=q.height*scale;s+=`<rect x="${x}" y="${y}" width="${Math.max(.4,w)}" height="${Math.max(.5,h)}" fill="${q.color}" stroke="#46596a" stroke-width="${q.kind==='stair'?.45:.65}" fill-opacity="${q.kind==='wall'?.38:1}"/>`}}
 const labels=[...data.levels].reverse().map(l=>({l,y:sy(l.z)}));for(let i=1;i<labels.length;i++)labels[i].y=Math.max(labels[i].y,labels[i-1].y+48);const overflow=Math.max(0,(labels.at(-1)?.y||0)-(bottom+10));for(const item of labels){const {l}=item,y=item.y-overflow,short=String(l.name).length>31?String(l.name).slice(0,30)+'…':l.name;s+=`<path d="M280 ${y-4}L310 ${sy(l.z)}" fill="none" stroke="#98a7b2"/><text x="55" y="${y-10}" font-size="18" font-weight="bold">${esc(l.id)} · ${fmt(l.z)}</text><text x="55" y="${y+10}" font-size="14" fill="#596979"><title>${esc(l.name)}</title>${esc(short)}</text>`}
 const bar=Math.max(1,Math.round(Math.min(10,spanX/4)/5)*5),barX=width-65-bar*scale,barY=height-70;s+=`<path d="M${barX} ${barY}h${bar*scale}m0-4v8m-${bar*scale}-8v8" stroke="#253240" stroke-width="2" fill="none"/><text x="${barX}" y="${barY+24}" font-size="14">${bar} m</text><text x="55" y="${height-70}" font-size="14" fill="#596979">3 m walls and 0.3 m slabs where unspecified. Required stair openings shown.</text><text x="55" y="${height-44}" font-size="14" fill="#596979">Concept preview · no roofs, structural engineering or traversal certification.</text></g></svg>`;return s;
}
function currentGeometry(){return window.BuildingPreviewGeometry.build(clone(model),window.KERN_STAIR_DETAIL)}
function downloadBlob(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function svgToPNG(svg){return new Promise((resolve,reject)=>{const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{try{const max=2800,ratio=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);const ctx=canvas.getContext('2d');if(!ctx)throw Error('Image export is unavailable in this browser.');ctx.fillStyle='#f7f7f2';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(result=>result?resolve(result):reject(Error('Could not create the PNG. Try the SVG export.')),'image/png')}catch(e){reject(e)}finally{URL.revokeObjectURL(url)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not render this drawing. Try the SVG export.'))};img.src=url})}
async function png(svg,name,button){if(pngBusy)return;pngBusy=true;const label=button?.innerHTML;if(button){button.disabled=true;button.setAttribute('aria-busy','true')}notify('Preparing PNG…');try{downloadBlob(name,await svgToPNG(svg));notify('PNG downloaded · generated from the current building')}catch(error){window.KERN_UI.openManagement('message',{title:'PNG export could not finish',message:error.message})}finally{pngBusy=false;if(button){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=label}}}
$('pngexport').onclick=()=>{prepare();return png(floorSheet(),`${fileName(currentBuilding().name)}-${fileName(floorId)}-plan.png`,$('pngexport'))};
$('svgexport').onclick=()=>{prepare();downloadBlob(`${fileName(currentBuilding().name)}-${fileName(floorId)}-plan.svg`,new Blob([floorSheet()],{type:'image/svg+xml'}));notify('SVG downloaded · editable current-floor drawing')};
$('stackpngexport').onclick=()=>{prepare();return png(stackSheet(currentGeometry(),currentBuilding().name),`${fileName(currentBuilding().name)}-vertical-stack.png`,$('stackpngexport'))};
function openStack(){prepare();const name=currentBuilding().name,data=currentGeometry();stackSnapshot={name,svg:stackSheet(data,name)};$('stacktitle').textContent=`${name} · Vertical stack`;$('stackdrawing').innerHTML=stackSnapshot.svg;$('stackassumptions').textContent=data.assumptions;$('stackdialog').showModal()}
$('openstack').onclick=openStack;$('closestack').onclick=()=>$('stackdialog').close();$('savestackpng').onclick=()=>stackSnapshot&&png(stackSnapshot.svg,`${fileName(stackSnapshot.name)}-vertical-stack.png`,$('savestackpng'));$('stackdialog').onclose=()=>{stackSnapshot=null;$('stackdrawing').innerHTML=''};
function loadThree(){if(window.Building3D)return Promise.resolve(window.Building3D);if(!threePromise)threePromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='preview3d.js';const timer=setTimeout(()=>{threePromise=null;script.remove();reject(Error('Loading the 3D renderer timed out. Close the preview and try again.'))},20000);script.onload=()=>{clearTimeout(timer);window.Building3D?resolve(window.Building3D):reject(Error('The 3D renderer did not start.'))};script.onerror=()=>{clearTimeout(timer);threePromise=null;script.remove();reject(Error('The 3D renderer could not load. Check your connection and try again.'))};document.head.appendChild(script)});return threePromise}
function disposeThree(){threeToken++;threeView?.dispose();threeView=null;$('threeviewport').innerHTML='';$('save3dpng').disabled=true}
function syncFloorChecks(ids){for(const input of $('threefloors').querySelectorAll('input'))input.checked=ids.includes(input.dataset.floor3d)}
function failedThree(message){$('threestatus').hidden=false;$('threestatus').textContent=message+' The floor-plan editor still works; use Vertical stack below.';$('save3dpng').disabled=true;for(const id of ['threefit','threeall','threeexplode','threewalls','threecutaway','threelabels','threexray'])$(id).disabled=true}
async function openThree(){
 prepare();disposeThree();const token=threeToken;threeName=currentBuilding().name;let data;
 $('preview3dtitle').textContent=`${threeName} · 3D`;$('threestatus').hidden=false;$('threestatus').textContent='Loading 3D preview…';$('threefloors').innerHTML='';$('threewarnings').open=false;$('save3dpng').disabled=true;
 $('threeexplode').value='0';$('explodelabel').textContent='0 m';$('threeexplode').setAttribute('aria-valuetext','0 metres');$('threewalls').checked=true;$('threecutaway').checked=false;$('threelabels').checked=true;$('threexray').checked=true;$('threehover').hidden=true;$('threefocusstatus').hidden=true;
 for(const id of ['threefit','threeall','threeexplode','threewalls','threecutaway','threelabels','threexray'])$(id).disabled=true;
 $('buildingpreview3d').showModal();
 try{data=currentGeometry();$('threeassumptions').textContent=data.assumptions;$('threewarningcount').textContent=data.warnings.length;$('threewarninglist').innerHTML=data.warnings.length?data.warnings.map(w=>`<p>${esc(w)}</p>`).join(''):'<p>No geometry warnings from this preview.</p>';
  $('threefloors').innerHTML=[...data.levels].reverse().map(l=>`<div><label><input type="checkbox" checked data-floor3d="${esc(l.id)}"><span><b>${esc(l.id)}</b> ${esc(l.name)}<small>${fmt(l.z)}</small></span></label><button data-isolate3d="${esc(l.id)}" title="Show only ${esc(l.id)}" aria-label="Show only ${esc(l.id)}">Only</button></div>`).join('');
  const library=await loadThree();if(token!==threeToken||!$('buildingpreview3d').open)return;
  threeView=library.mount($('threeviewport'),data,{onHover:level=>{$('threehover').hidden=!level;$('threehover').textContent=level?level.id+' · '+level.name+' · click to focus':''},onVisibilityChanged:(ids,focused)=>{syncFloorChecks(ids);$('threefocusstatus').hidden=!focused;$('threefocusstatus').textContent=focused?'Focused: '+focused+' · Escape or Show all returns to the overview':''},onContextLost:()=>{disposeThree();failedThree('The graphics context was lost. Close and reopen the preview.')}});$('threestatus').hidden=true;$('save3dpng').disabled=false;
  for(const id of ['threefit','threeall','threeexplode','threewalls','threecutaway','threelabels','threexray'])$(id).disabled=false;
  if(!data.levels.some(l=>l.boxes.length)){$('threestatus').hidden=false;$('threestatus').textContent='This building is empty. Draw a room in the editor to give it a 3D shape.'}
 }catch(error){if(token===threeToken){disposeThree();failedThree(/WebGL|context|renderer/i.test(error.message)?'3D needs WebGL 2, which is unavailable in this browser.':error.message)}}
}
$('open3d').onclick=openThree;$('close3d').onclick=()=>$('buildingpreview3d').close();$('buildingpreview3d').onclose=disposeThree;
$('threefit').onclick=()=>threeView?.fit();$('threeall').onclick=()=>{threeView?.showAll();syncFloorChecks(Object.keys(model.floors))};
$('threefloors').onchange=e=>{if(e.target.dataset.floor3d)threeView?.setFloor(e.target.dataset.floor3d,e.target.checked)};
$('threefloors').onclick=e=>{const id=e.target.closest('button')?.dataset.isolate3d;if(id){threeView?.isolate(id);syncFloorChecks([id])}};
$('threeexplode').oninput=e=>{$('explodelabel').textContent=`${e.target.value} m`;$('threeexplode').setAttribute('aria-valuetext',`${e.target.value} metres`);threeView?.setExplode(e.target.value)};
$('threeexplode').onchange=()=>threeView?.fit();$('threewalls').onchange=e=>threeView?.setWalls(e.target.checked);$('threecutaway').onchange=e=>threeView?.setCutaway(e.target.checked);$('threelabels').onchange=e=>threeView?.setLabels(e.target.checked);$('threexray').onchange=e=>threeView?.setXray?.(e.target.checked);
$('threefallback').onclick=()=>{$('buildingpreview3d').close();openStack()};
$('buildingpreview3d').addEventListener('cancel',e=>{if(threeView?.getFocusedFloor?.()){e.preventDefault();threeView.showAll()}});
$('threefloors').addEventListener('pointerover',e=>{const row=e.target.closest('[data-isolate3d]')||e.target.closest('div')?.querySelector('[data-isolate3d]');if(row)threeView?.hoverFloor?.(row.dataset.isolate3d)});$('threefloors').addEventListener('pointerleave',()=>threeView?.hoverFloor?.(null));
$('save3dpng').onclick=async()=>{if(!threeView)return;const viewer=threeView,name=threeName;$('save3dpng').disabled=true;try{downloadBlob(`${fileName(name)}-3d-preview.png`,await viewer.png());notify('3D snapshot downloaded')}catch(error){$('threestatus').hidden=false;$('threestatus').textContent='Could not save the snapshot. '+error.message}finally{if(viewer===threeView)$('save3dpng').disabled=false}};
window.BuildingExports={floorSheet,stackSheet,currentGeometry,svgToPNG,openStack,openThree,disposeThree};
})();
